using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(b =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            b.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so we must opt back in.
            b.HasPartitionKey(e => e.Id);
            b.Property(e => e.Id)
                .HasJsonPropertyName("id")
                .ToJsonProperty("id");

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws by default in EF 9 for Cosmos provider.
            // Removed the HasIndex call — use Cosmos indexing policy instead.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

