class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses role-based RBAC by default and sync I/O
        // now throws. Use async methods instead.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();

        // Breaking change 5: Raw SQL queries referencing c.Discriminator still work
        // only because we explicitly preserved "Discriminator" in OnModelCreating.
        // Without that fix, EF 9 would write "$type" and old queries like:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // would return no results.
    }
}

